import { createClient } from "@libsql/client";
import { readFileSync } from "fs";
import path from "path";

const url = process.env.TURSO_DATABASE_URL || process.env.DATABASE_URL;
const authToken = process.env.TURSO_AUTH_TOKEN || process.env.DATABASE_AUTH_TOKEN;

if (!url || !url.startsWith("libsql")) {
  console.error("Set TURSO_DATABASE_URL to a libsql:// URL");
  process.exit(1);
}

// FIRST-TIME INSTALL ONLY. This cannot migrate an existing database.
//
// prisma/schema.sql is generated by `prisma migrate diff --from-empty`, so every
// statement is `CREATE TABLE IF NOT EXISTS`. On a database that already has the
// table, that is a silent no-op: this script prints "pushed successfully" and
// changes nothing. It will therefore NOT add a column added to schema.prisma
// after the initial push -- which is how production ended up without
// Service.isCatchAll while local dev (on real migrations) always had it.
//
// To change an existing database, run the idempotent migration that owns the
// change, e.g. `npm run db:migrate-prod`. Use `npm run db:check-drift` to find
// out what is missing. This script is only for bootstrapping an empty database.

const client = createClient({ url, authToken });

const schemaFile = path.join(process.cwd(), "prisma", "schema.sql");
const schema = readFileSync(schemaFile, "utf-8");

// Split on ';' but ignore comment-only lines first. A previous version filtered
// chunks that started with "--" *after* splitting, which discarded any statement
// preceded by a `-- CreateTable` annotation: 0 statements were pushed and the
// script still reported success. Fail loudly instead of silently doing nothing.
const stmts = schema
  .split("\n")
  .filter((line) => !line.trim().startsWith("--"))
  .join("\n")
  .split(";")
  .map((s) => s.trim())
  .filter((s) => s.length > 0);

if (stmts.length === 0) {
  console.error(
    "Refusing to push: prisma/schema.sql produced 0 statements.\n" +
      "Regenerate it with `npm run db:schema-sql`.",
  );
  process.exit(1);
}

async function main() {
  // executeMultiple runs the whole script in one implicit transaction, so a
  // failure part-way through rolls back instead of leaving a half-built schema.
  await client.executeMultiple(schema);

  console.log(`Schema pushed successfully (${stmts.length} statements).`);
}

main().catch((e) => {
  console.error("Schema push FAILED:", e);
  process.exit(1);
});
